    p: Annotated[List[str], Body(embed=True, validation_alias="p_val_alias")],
):
    return {"p": p}

client = TestClient(app)

def test_validation_alias():
    print("Testing /test_validation_alias with p_val_alias...")
    response = client.post("/test_validation_alias", json={"p_val_alias": ["a", "b"]})
    print(f"Response status code: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"p": ["a", "b"]}

if __name__ == "__main__":
    try:
        test_validation_alias()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)
